-- Jeu de LecteurPivoterPages (« Pivoter des pages », PROC_PDF_WRITER), lot 5 du plan « RIG v3 complet, mesure par le banc du
-- parcours complet » (plan-f4fb097f, 28/11/2026). Documents 3500101, 3500105, 3500106 (plage du lot : (30 + 5) x 100000). Ce qui est
-- retenu ou ecarte, et pourquoi : PROC_PDF_WRITER.attendu.
-- LA MEME LISTE QUE « Documents ocerises » (PROC_NUM) : RIG v2 n'ouvre PDF_WRITER que depuis elle (PROC_NUM_PROC.cs:160-215), le
-- lecteur relit donc la requete de LecteurDocumentsOcerises, et tout document ajoute ici entre aussi dans PROC_NUM.attendu et dans
-- les « lignes: » de PROC_NUM.gestes. Les cas deja poses par PROC_NUM.sql servent tels quels : un PDF sans fichier (2110301, 2110305),
-- des TIF (2110302, 2110304), un document lie a l'OCR differe (2110303). Ce jeu n'ajoute que ce qui y manque.
-- fix-ok: mesure au banc EcransGeneresBaseCheck (28/11/2026) -- la premiere version posait six documents, dont cinq entraient dans la
-- liste de PROC_NUM (meme table, meme filtre) : « PROC_NUM : total = 4 lignes attendues (9) » et trois blocs de PROC_NUM.gestes rouges.
-- La table est celle de PROC_NUM.sql (memes types, ceux de RIG_DEV).
IF OBJECT_ID(N'v2.DOCUMENT_OCERISE') IS NULL
    CREATE TABLE v2.DOCUMENT_OCERISE (DOCOC_ID_DOCOC int NOT NULL PRIMARY KEY, DOCOC_NOM_FICHIER varchar(255) NULL,
        DOCOC_DATE_CREATION datetime NULL, DOCOC_ID_UTLST int NULL, DOCOC_NB_PAGES int NULL, DOCOC_TAILLE int NULL,
        DOCOC_NUM_JUD varchar(20) NULL, DOCOC_CODE_PROCESSUS varchar(40) NULL, DOCOC_ID_UTLST_EN_COURS int NULL,
        DOCOC_CODE_PROC_EN_COURS varchar(40) NULL, DOCOC_DATE_EN_COURS datetime NULL, DOCOC_IS_LIE_OCR_DIFFERE bit NULL);
-- Le fichier du document : varbinary(max) dans RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV, lu le 27/11/2026, PROC_NUM.sql).
IF COL_LENGTH('v2.DOCUMENT_OCERISE', 'DOCOC_FICHIER') IS NULL ALTER TABLE v2.DOCUMENT_OCERISE ADD DOCOC_FICHIER varbinary(max) NULL;
-- sp_executesql : la colonne ajoutee ci-dessus n'existe pas encore quand ce lot est compile.
EXEC sp_executesql N'
INSERT INTO v2.DOCUMENT_OCERISE (DOCOC_ID_DOCOC, DOCOC_NOM_FICHIER, DOCOC_DATE_CREATION, DOCOC_NB_PAGES, DOCOC_TAILLE, DOCOC_NUM_JUD,
                                 DOCOC_ID_UTLST_EN_COURS, DOCOC_CODE_PROC_EN_COURS, DOCOC_DATE_EN_COURS, DOCOC_IS_LIE_OCR_DIFFERE, DOCOC_FICHIER) VALUES
    -- un VRAI PDF de deux pages, la 2e deja tournee a 90° (/Rotate 90), table de renvois classique, 828 octets (valide pour qpdf
    -- 12.4 et Windows.Data.Pdf, 28/11/2026) : PDF_WRITER l ouvre et « Enregistrer le PDF » le tourne (PROC_PDF_WRITER.gestes) --
    -- jumeau des PDF sans fichier 2110301 et 2110305
    (3500101, ''contrat du banc 5.pdf'', ''20010610'', 2, 828, ''2001J00051'', NULL, NULL, NULL, 0, ),
    -- un PDF au fichier VIDE (0 octet, pas NULL) : meme refus que sans fichier, « Le fichier est corrompu. » -- jumeau 3500101
    (3500106, ''vide du banc 5.pdf'', ''20010609'', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0x),
    -- un PDF et son fichier, qu un processus tient en cours (la reservation de la V2) -- jumeau 3500101, libre ; son fichier n est que
    -- l en-tete %PDF-1.4 : « Enregistrer le PDF » le dit illisible (PROC_PDF_WRITER.gestes)
    (3500105, ''tenu du banc 5.pdf'', ''20010606'', 5, 9000, NULL, 7, ''NUM'', ''20010606'', 0, 0x255044462D312E340A);';
-- L'agent des gestes faits (PROC_PDF_WRITER.gestes) : un compte qui a son utilisateur RIG v2 (soc.Compte.IdV2, plage du lot), ecrit
-- dans DOCOC_ID_UTLST comme l'utilisateur courant de RIG v2 (PROC_NUM_PROC.cs:267) ; admis dans le greffe comme l'agent du banc.
IF NOT EXISTS (SELECT 1 FROM soc.Compte WHERE CompteWindows = 'banc.l5.pdf')
BEGIN
    INSERT INTO soc.Compte (IdV2, CompteWindows, Nom, Prenom, Abrege, Civilite, CodeGreffe, IdService, Desactive)
    SELECT 3500001, 'banc.l5.pdf', 'PIVOT', 'Banc', 'BANCL5', 'M.', CodeGreffe, IdService, 0 FROM soc.Compte WHERE CompteWindows = 'banc.ecrans';
    INSERT INTO soc.CompteRole (IdCompte, Role) SELECT Id, 'BANC' FROM soc.Compte WHERE CompteWindows = 'banc.l5.pdf';
END
-- Et un compte SANS utilisateur RIG v2 (IdV2 NULL) : DOCOC_ID_UTLST ecrit NULL (l'agent du banc en a un, pose par un autre jeu).
IF NOT EXISTS (SELECT 1 FROM soc.Compte WHERE CompteWindows = 'banc.l5.sansv2')
BEGIN
    INSERT INTO soc.Compte (CompteWindows, Nom, Prenom, Abrege, Civilite, CodeGreffe, IdService, Desactive)
    SELECT 'banc.l5.sansv2', 'SANSV2', 'Banc', 'BANCL5S', 'M.', CodeGreffe, IdService, 0 FROM soc.Compte WHERE CompteWindows = 'banc.ecrans';
    INSERT INTO soc.CompteRole (IdCompte, Role) SELECT Id, 'BANC' FROM soc.Compte WHERE CompteWindows = 'banc.l5.sansv2';
END
